//! The display profiles: for each, the display, the font vtium draws on it,
//! the grid that gives, and how the card's blocks are arrayed on it.

use vtium_render::Depth;

use crate::card::{BLOCK_COLS, BLOCK_ROWS, BLOCKS};

/// What a profile draws its text with.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Glyphs {
    /// A set built into vtium (ADR-1200 D7), drawn at `height` pixels.
    Builtin { set: &'static str, height: u32 },
    /// The desktop frit, `frits/desktop.vtfrit`, its glyphs generated by
    /// vtium-vitrify's engine from the pinned outline fonts of
    /// [`crate::fonts`] in the profile's cell, `height` pixels high.
    Desktop { height: u32 },
}

impl Glyphs {
    /// The set's name, as `font-name` and the card's header give it.
    pub fn set(self) -> &'static str {
        match self {
            Glyphs::Builtin { set, .. } => set,
            Glyphs::Desktop { .. } => "desktop",
        }
    }

    /// The cell height asked of the set.
    pub fn height(self) -> u32 {
        match self {
            Glyphs::Builtin { height, .. } | Glyphs::Desktop { height } => height,
        }
    }
}

/// One display profile.
#[derive(Clone, Copy, Debug)]
pub struct Profile {
    /// Its directory under `docs/specimens/`.
    pub name: &'static str,
    pub width: u32,
    pub height: u32,
    /// The display's depth, as the card's header names it.
    pub depth: &'static str,
    /// The display class it falls in, by the display-capabilities record's
    /// table (vtium/vtium#136).
    pub class: &'static str,
    /// How vtium-render draws it: `display-depth`.
    pub display: Depth,
    pub glyphs: Glyphs,
    /// The cell the set draws at that height, which the drawing must give.
    pub cell: (u32, u32),
    /// What it is, one line, for the tables.
    pub summary: &'static str,
    /// Why this font and size is the best choice on this display.
    pub why: &'static str,
    /// The vtium.conf lines for the profile, comments included.
    pub conf: &'static str,
    /// For a gray panel, the conversion its driver applies to vtium's color
    /// drawing, which the profile's renders simulate.
    pub panel: Option<Panel>,
}

/// An XRGB8888 pixel's gray8, BT.601 luma in the kernel's integers:
/// `(77r + 150g + 29b) / 256` (Linux v7.3,
/// `drivers/gpu/drm/drm_format_internal.h:39-47`).
pub fn gray8(rgb: [u8; 3]) -> u8 {
    let [r, g, b] = rgb.map(u32::from);
    ((77 * r + 150 * g + 29 * b) / 256) as u8
}

/// A gray panel's conversion, as its Linux driver makes it from the
/// XRGB8888 framebuffer vtium draws (Linux v7.3). Each pixel goes to gray8
/// by BT.601 luma, `(77r + 150g + 29b) / 256`
/// (`drivers/gpu/drm/drm_format_internal.h:39-47`, through
/// `drm_fb_xrgb8888_to_gray8`, `drivers/gpu/drm/drm_format_helper.c:1084-1126`),
/// then to the panel's levels by the gray8 value's top bits.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Panel {
    /// st7586's 4 levels: gray8 shifted right 6, then its lookup table
    /// (`drivers/gpu/drm/sitronix/st7586.c:80-106`).
    St7586,
    /// The SSD132x panels' 16 levels: gray8's top nibble, two pixels a byte
    /// (`drivers/gpu/drm/solomon/ssd130x.c:968` and `:801-809`).
    Ssd132x,
}

impl Panel {
    /// The bits of gray8 the panel keeps.
    pub fn bits(self) -> u32 {
        match self {
            Panel::St7586 => 2,
            Panel::Ssd132x => 4,
        }
    }

    /// The driver's name and source, for the READMEs.
    pub fn driver(self) -> &'static str {
        match self {
            Panel::St7586 => {
                "st7586 (`drivers/gpu/drm/sitronix/st7586.c:80-106`: gray8 >> 6, its 4 levels through `st7586_lookup`)"
            }
            Panel::Ssd132x => {
                "ssd130x's SSD132x path (`drivers/gpu/drm/solomon/ssd130x.c:968` and `:801-809`: gray8 >> 4, two 4-bit pixels a byte)"
            }
        }
    }

    /// `rgb`, one pixel, as the panel shows it: its level drawn as the gray
    /// that level is on a panel whose levels are evenly spaced.
    pub fn show(self, rgb: [u8; 3]) -> u8 {
        let level = u32::from(gray8(rgb)) >> (8 - self.bits());
        let top = (1 << self.bits()) - 1;
        (level * 255 / top) as u8
    }
}

/// How a profile's grid holds the card: the blocks a page holds across and
/// down, where the first sits, and the pages the card takes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Layout {
    pub cols: usize,
    pub rows: usize,
    pub across: usize,
    pub down: usize,
    /// The first block's top row and left column: the blocks are centered.
    pub top: usize,
    pub left: usize,
    pub pages: usize,
}

impl Layout {
    /// The layout of a grid `cols` by `rows`; `None` for a grid smaller
    /// than one block.
    pub fn new(cols: usize, rows: usize) -> Option<Layout> {
        let across = cols / BLOCK_COLS;
        let down = rows / BLOCK_ROWS;
        let per_page = across * down;
        if per_page == 0 {
            return None;
        }
        Some(Layout {
            cols,
            rows,
            across,
            down,
            top: (rows - down * BLOCK_ROWS) / 2,
            left: (cols - across * BLOCK_COLS) / 2,
            pages: BLOCKS.div_ceil(per_page),
        })
    }

    /// The blocks page `page` holds, each with its top row and left column.
    pub fn blocks(&self, page: usize) -> impl Iterator<Item = (usize, usize, usize)> + '_ {
        let per_page = self.across * self.down;
        (page * per_page..((page + 1) * per_page).min(BLOCKS)).map(move |b| {
            let i = b % per_page;
            (
                b,
                self.top + (i / self.across) * BLOCK_ROWS,
                self.left + (i % self.across) * BLOCK_COLS,
            )
        })
    }
}

const UNSCII_WHY: &str = "ADR-1200 D7 draws the built-in Unscii-8 for cells under 16 pixels high, and #118's rule has `font-size=0` take a set's smallest height when 16-pixel cells would leave fewer than 80x25 of them, so vtium draws this display in 8x8 cells with no font keys at all. It is the most text the display holds at a cell a person can still read, and it costs no disk: D11 builds nothing beyond the built-ins for an English machine at this size. Unscii-8 holds no CJK or Hangul, nor the emoji and private-use symbols, so those draw as the missing glyph, U+25A1, until #141's per-character fallback draws them from unifont; in a zh, ja or ko locale D7 draws unifont at 16 pixels instead.";

const UNIFONT_WHY: &str = "16-pixel cells leave at least 80x25 here, so #118's rule keeps `font-size=0`'s 16 pixels, and ADR-1200 D7 draws the built-in unifont from 16 pixels: 8x16 cells for Latin, Greek and Cyrillic and 16x16 for CJK and Hangul, which it covers whole, with nothing built. The size the display wants is under 24 pixels, the smallest outline size D11 builds, so a default machine holds no outline set for it. Emoji draw as unifont's monochrome glyphs where it has one, and Nerd Font symbols as the missing glyph; the outline profiles draw both from the desktop set.";

const GRAY_WHY: &str = "vtium draws a gray panel exactly as a color display and lets the panel's driver convert each pixel (#135): the screens here are the color profile's drawing taken through the driver's arithmetic, a simulation of what the panel shows, not vtium's output. The font is the color profile's at this size, for the same reasons; a gray panel's few levels keep the bitmap glyphs crisp, and the card's gray bands show which levels survive the conversion.";

const ONE_BIT_WHY: &str = "A 1-bit panel lights a pixel or does not, so a bitmap font, 1-bit already, draws on it exactly: the built-in Unscii-8 at 8x8 gives the same 40x30 cells as the color profile, for the reasons that profile gives. vtium-render maps each cell's colors to lit or unlit by the cell, never by brightness, with polarity from the default background, and cuts every coverage at half (#135): colors show only where a cell's background differs from the default, dim draws as plain text, and the shades draw as ordered patterns.";

const DESKTOP_WHY: &str = "ADR-1200 D11 builds one outline size for the display the package hook sees, snapped down to 24, 32 or 48 pixels, with unifont filling the outline font's gaps. The desktop frit starts at 18 points, 24 pixels at 96 DPI, and these profiles draw it in 24- and 32-pixel cells, from JetBrains Mono for text, Symbols Nerd Font Mono for the private-use symbols and Noto Color Emoji for emoji, with the built-in unifont last; `font-size=0` picks the strike, the largest whole multiple of a strike's height under the size it asks (ADR-1200 D9). Outline glyphs draw antialiased at this size. A set maps single codepoints, so ZWJ sequences, flags and keycaps draw as their parts until #144 shapes them, and the scripts that need shaping draw unshaped.";

const DESKTOP_CONF: &str = "# The desktop frit: tools/specimens/frits/desktop.vtfrit in\n# /etc/vtium/fonts, its glyphs generated at run time (ADR-1301 D2).\nfont-name=desktop\nfont-size=0\n";

