impl Profile {
    /// The layout of the card on this profile's display in its cells.
    pub fn layout(&self) -> Result<Layout, String> {
        let cols = (self.width / self.cell.0) as usize;
        let rows = (self.height / self.cell.1) as usize;
        Layout::new(cols, rows).ok_or_else(|| {
            format!(
                "{}: a grid of {cols}x{rows} holds no block of {BLOCK_COLS}x{BLOCK_ROWS}",
                self.name
            )
        })
    }
}

/// The profile named `name`.
pub fn profile(name: &str) -> Option<&'static Profile> {
    PROFILES.iter().find(|p| p.name == name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_blocks_are_centered_and_paged() {
        let l = Layout::new(40, 30).unwrap();
        assert_eq!((l.across, l.down, l.top, l.left, l.pages), (1, 1, 0, 0, 5));
        let l = Layout::new(60, 40).unwrap();
        assert_eq!((l.top, l.left, l.pages), (5, 10, 5));
        let l = Layout::new(80, 30).unwrap();
        assert_eq!(l.pages, 3);
        assert_eq!(l.blocks(1).collect::<Vec<_>>(), vec![(2, 0, 0), (3, 0, 40)]);
        assert_eq!(l.blocks(2).collect::<Vec<_>>(), vec![(4, 0, 0)]);
        let l = Layout::new(170, 48).unwrap();
        assert_eq!((l.top, l.left, l.pages), (9, 5, 2));
        assert_eq!(
            l.blocks(0).map(|b| b.2).collect::<Vec<_>>(),
            [5, 45, 85, 125]
        );
        assert_eq!(Layout::new(39, 30), None);
        assert_eq!(Layout::new(40, 29), None);
    }

    // BT.601 luma by the kernel's integers, then the panel's top bits:
    // pure red is gray8 76 (19635 / 256), level 1 of 4 and 4 of 16; pure
    // green 149, level 9 of 16.
    // The kernel's own figures for gray8 before any panel quantizes it:
    // pure red, green and blue at 255 (drm_format_internal.h:39-47).
    #[test]
    fn gray8_is_the_kernel_s_bt601_luma() {
        assert_eq!(gray8([255, 0, 0]), 76);
        assert_eq!(gray8([0, 255, 0]), 149);
        assert_eq!(gray8([0, 0, 255]), 28);
        assert_eq!(gray8([255, 255, 255]), 255);
        assert_eq!(gray8([0, 0, 0]), 0);
    }

    #[test]
    fn a_gray_panel_keeps_the_top_bits_of_bt601_luma() {
        assert_eq!(Panel::St7586.show([255, 0, 0]), 85);
        assert_eq!(Panel::Ssd132x.show([255, 0, 0]), 68);
        assert_eq!(Panel::St7586.show([127, 127, 127]), 85);
        assert_eq!(Panel::Ssd132x.show([127, 127, 127]), 119);
        assert_eq!(Panel::St7586.show([255, 255, 255]), 255);
        assert_eq!(Panel::Ssd132x.show([255, 255, 255]), 255);
        assert_eq!(Panel::St7586.show([0, 0, 0]), 0);
        assert_eq!(Panel::Ssd132x.show([0, 255, 0]), 153);
    }

    #[test]
    fn every_profile_has_a_unique_name_and_a_conf() {
        for (i, p) in PROFILES.iter().enumerate() {
            assert!(PROFILES[..i].iter().all(|q| q.name != p.name), "{}", p.name);
            assert!(p.conf.ends_with("font-size=0\n"), "{}", p.name);
        }
    }
}
